// Enfeites desenhados à mão (SVG): o lírio rosa do buquê dela e um brilhinho.

const PETALAS = [0, 60, 120, 180, 240, 300];

export function Lirio({ tamanho = 64, className = "", style }) {
  return (
    <svg
      className={`faby-lirio ${className}`}
      viewBox="0 0 100 100"
      width={tamanho}
      height={tamanho}
      aria-hidden="true"
      style={style}
    >
      <defs>
        <radialGradient id="lirio-petala" cx="50%" cy="100%" r="100%">
          <stop offset="0%" stopColor="#fff4f8" />
          <stop offset="35%" stopColor="#ffb3cf" />
          <stop offset="100%" stopColor="#f47fab" />
        </radialGradient>
      </defs>
      {PETALAS.map((giro, i) => (
        <g key={giro} transform={`rotate(${giro + (i % 2 ? 4 : 0)} 50 50)`}>
          <path
            d={i % 2 ? "M50 50 C42 36 42 20 50 8 C58 20 58 36 50 50Z" : "M50 50 C40 34 41 14 50 2 C59 14 60 34 50 50Z"}
            fill="url(#lirio-petala)"
            stroke="#ee7aa6"
            strokeWidth="1"
          />
          <path d="M50 46 L50 18" stroke="#e8629b" strokeWidth="1.4" strokeLinecap="round" opacity="0.55" />
        </g>
      ))}
      <circle cx="50" cy="50" r="7" fill="#fff6e0" />
      {[20, 80, 140, 200, 260, 320].map((giro) => (
        <g key={giro} transform={`rotate(${giro} 50 50)`}>
          <line x1="50" y1="50" x2="50" y2="28" stroke="#c9e3a0" strokeWidth="1.2" />
          <ellipse cx="50" cy="27" rx="2.2" ry="3.4" fill="#d9774f" />
        </g>
      ))}
    </svg>
  );
}

export function Brilho({ tamanho = 18, className = "", style }) {
  return (
    <svg
      className={`faby-brilho ${className}`}
      viewBox="0 0 24 24"
      width={tamanho}
      height={tamanho}
      aria-hidden="true"
      style={style}
    >
      <path d="M12 0 C13 8 16 11 24 12 C16 13 13 16 12 24 C11 16 8 13 0 12 C8 11 11 8 12 0Z" fill="currentColor" />
    </svg>
  );
}
