import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ChevronLeft, ChevronRight, RefreshCcw } from "lucide-react";
import { FOTOS, POLAROIDS, SECOES } from "./content";
import { diaDeHoje } from "./Bilhetinho";
import PixelSprite from "./PixelSprite";
import Secao from "./Secao";

// Cada foto tem a sua inclinação, pra pilha parecer jogada em cima da mesa.
const GIROS = [-4, 3, -2, 5, -5, 2, -3, 4, -1, 3, -4, 2, -2];
const ENFEITES = ["heart", "star", "bow", "strawberry"];
const ARRASTO = 80;

const src = (id) => `/faby/fotos/${id}.webp`;

// Um baralho de polaroids: arrasta a de cima pro lado pra ela ir pro fim da pilha,
// toca pra virar e ler o verso. Começa numa foto diferente a cada dia.
function Polaroids() {
  const reduzir = useReducedMotion();
  const [ordem, setOrdem] = useState(() => {
    const inicio = diaDeHoje() % FOTOS.length;
    return FOTOS.map((_, i) => (i + inicio) % FOTOS.length);
  });
  const [virada, setVirada] = useState(false);
  const [saida, setSaida] = useState(1);

  const proxima = (lado = 1) => {
    setSaida(lado);
    setVirada(false);
    setOrdem((o) => [...o.slice(1), o[0]]);
  };
  const anterior = () => {
    setSaida(0);
    setVirada(false);
    setOrdem((o) => [o[o.length - 1], ...o.slice(0, -1)]);
  };

  const topo = ordem[0];
  const visiveis = ordem.slice(0, 3);
  const posicao = topo + 1;

  return (
    <Secao titulo={SECOES.fotos} className="faby-polaroids">
      <div className="faby-pilha" aria-roledescription="carrossel" aria-label={SECOES.fotos}>
        <AnimatePresence initial={false} custom={saida}>
          {visiveis
            .map((indice, camada) => {
              const foto = FOTOS[indice];
              const giro = GIROS[indice % GIROS.length];
              const emCima = camada === 0;
              return (
                <motion.div
                  key={foto.id}
                  className="faby-polaroid-lugar"
                  custom={saida}
                  style={{ zIndex: 3 - camada }}
                  initial={{ opacity: 0, scale: 0.9, y: 24, rotate: giro }}
                  animate={{
                    opacity: 1,
                    scale: 1 - camada * 0.05,
                    y: camada * 14,
                    x: 0,
                    rotate: emCima ? giro * 0.4 : giro,
                  }}
                  exit={(lado) => ({
                    // a de cima voa pro lado do arrasto; voltando, a do fundo só some
                    x: lado * 380,
                    rotate: lado * 24,
                    scale: lado ? 1 : 0.85,
                    opacity: 0,
                    transition: { duration: reduzir ? 0 : 0.42, ease: [0.32, 0.72, 0, 1] },
                  })}
                  transition={{ type: "spring", stiffness: 220, damping: 24 }}
                  drag={emCima ? "x" : false}
                  dragSnapToOrigin
                  dragElastic={0.85}
                  whileDrag={{ scale: 1.03, cursor: "grabbing" }}
                  onDragEnd={(_, info) => {
                    if (Math.abs(info.offset.x) > ARRASTO || Math.abs(info.velocity.x) > 600) {
                      proxima(info.offset.x > 0 ? 1 : -1);
                    }
                  }}
                  onTap={emCima ? () => setVirada((v) => !v) : undefined}
                  aria-hidden={!emCima}
                >
                  <motion.figure
                    className="faby-polaroid"
                    animate={{ rotateY: emCima && virada ? 180 : 0 }}
                    transition={{ type: "spring", stiffness: 160, damping: 20 }}
                  >
                    <div className="faby-polaroid-frente">
                      <span className="faby-fita faby-fita-polaroid" aria-hidden="true" />
                      <img
                        src={src(foto.id)}
                        alt={foto.legenda}
                        width="720"
                        height="900"
                        draggable="false"
                        loading={camada === 0 ? "eager" : "lazy"}
                        decoding="async"
                      />
                      <figcaption>{foto.legenda}</figcaption>
                    </div>
                    <div className="faby-polaroid-verso" aria-hidden={!virada}>
                      <PixelSprite name={ENFEITES[indice % ENFEITES.length]} size={34} />
                      <p>{foto.verso}</p>
                      <span className="faby-polaroid-assinatura">— seu bb 🤍</span>
                    </div>
                  </motion.figure>
                </motion.div>
              );
            })
            .reverse()}
        </AnimatePresence>
      </div>

      <p className="faby-dica">{POLAROIDS.dica}</p>

      <div className="faby-polaroids-controles">
        <button type="button" className="faby-botao-redondo" onClick={anterior} aria-label={POLAROIDS.anterior}>
          <ChevronLeft strokeWidth={2.6} aria-hidden="true" />
        </button>
        <button type="button" className="faby-botao faby-botao-suave" onClick={() => setVirada((v) => !v)}>
          <RefreshCcw strokeWidth={2.4} size={16} aria-hidden="true" />
          {POLAROIDS.virar}
        </button>
        <button type="button" className="faby-botao-redondo" onClick={() => proxima(1)} aria-label={POLAROIDS.proxima}>
          <ChevronRight strokeWidth={2.6} aria-hidden="true" />
        </button>
      </div>

      <div className="faby-pontinhos" aria-hidden="true">
        {FOTOS.map((foto, i) => (
          <span key={foto.id} className={i === topo ? "is-atual" : undefined} />
        ))}
      </div>
      <span className="sr-only" aria-live="polite">
        {`foto ${posicao} de ${FOTOS.length}: ${FOTOS[topo].legenda}`}
      </span>
    </Secao>
  );
}

export default Polaroids;
