import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { ABERTURA, APELIDOS, RODAPE } from "./faby/content";
import PixelSprite from "./faby/PixelSprite";
import { Brilho, Lirio } from "./faby/Enfeites";
import Bilhetinho from "./faby/Bilhetinho";
import Cartinha from "./faby/Cartinha";
import Contador from "./faby/Contador";
import Final from "./faby/Final";
import Frasinhas from "./faby/Frasinhas";
import Motivos from "./faby/Motivos";
import Perguntas from "./faby/Perguntas";
import Polaroids from "./faby/Polaroids";
import "./Faby.css";

const FONTES =
  "https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;600;700;800&family=Quicksand:wght@400;500;600;700&family=Patrick+Hand&display=swap";

const ENFEITES = [
  { nome: "cloud", tamanho: 46, classe: "faby-enfeite-1" },
  { nome: "heart", tamanho: 18, classe: "faby-enfeite-2" },
  { nome: "star", tamanho: 16, classe: "faby-enfeite-3" },
  { nome: "cloud", tamanho: 34, classe: "faby-enfeite-4" },
  { nome: "bow", tamanho: 24, classe: "faby-enfeite-5" },
  { nome: "heart", tamanho: 14, classe: "faby-enfeite-6" },
];

// Pétalas de lírio caindo devagarinho pelo fundo.
const PETALAS = Array.from({ length: 9 }, (_, i) => i);

const BRILHOS = [
  { top: "6%", left: "8%", tamanho: 16, atraso: 0 },
  { top: "18%", right: "4%", tamanho: 22, atraso: 0.6 },
  { top: "62%", left: "2%", tamanho: 14, atraso: 1.2 },
  { top: "74%", right: "10%", tamanho: 12, atraso: 1.8 },
];

const EASE = [0.16, 1, 0.3, 1];

function useAmbientePagina() {
  useEffect(() => {
    const html = document.documentElement;
    const idiomaAntes = html.lang;
    const tituloAntes = document.title;
    const corAntes = document.querySelector('meta[name="theme-color"]')?.getAttribute("content");

    html.lang = "pt-BR";
    document.title = `${APELIDOS.fofo} 💗`;
    document.body.classList.add("faby-modo");
    document.querySelectorAll('meta[name="theme-color"]').forEach((m) => m.setAttribute("content", "#ffe4ef"));

    const semRobos = document.createElement("meta");
    semRobos.name = "robots";
    semRobos.content = "noindex, nofollow";
    document.head.appendChild(semRobos);

    const preconexao = document.createElement("link");
    preconexao.rel = "preconnect";
    preconexao.href = "https://fonts.gstatic.com";
    preconexao.crossOrigin = "anonymous";

    const fontes = document.createElement("link");
    fontes.rel = "stylesheet";
    fontes.href = FONTES;

    document.head.appendChild(preconexao);
    document.head.appendChild(fontes);

    return () => {
      html.lang = idiomaAntes;
      document.title = tituloAntes;
      document.body.classList.remove("faby-modo");
      if (corAntes) {
        document.querySelectorAll('meta[name="theme-color"]').forEach((m) => m.setAttribute("content", corAntes));
      }
      semRobos.remove();
      preconexao.remove();
      fontes.remove();
    };
  }, []);
}

// Conta as visitas dela (uma por sessão), guardado só no celular dela.
function useVisitas() {
  const [visitas, setVisitas] = useState(0);
  useEffect(() => {
    try {
      let total = Number(localStorage.getItem("faby-visitas")) || 0;
      if (!sessionStorage.getItem("faby-visitou")) {
        total += 1;
        localStorage.setItem("faby-visitas", String(total));
        sessionStorage.setItem("faby-visitou", "1");
      }
      setVisitas(total);
    } catch {
      setVisitas(0);
    }
  }, []);
  return visitas;
}

function Abertura() {
  const reduzir = useReducedMotion();
  const flutua = reduzir ? undefined : { y: [0, -8, 0] };

  const descer = () => {
    document.getElementById("faby-historinha")?.scrollIntoView({ behavior: reduzir ? "auto" : "smooth" });
  };

  return (
    <header className="faby-abertura">
      <div className="faby-abertura-palco">
        <motion.span
          className="faby-abertura-lirio faby-abertura-lirio-1"
          initial={{ opacity: 0, scale: 0.6, rotate: -30 }}
          animate={{ opacity: 1, scale: 1, rotate: -12 }}
          transition={{ duration: 0.9, delay: 0.35, ease: EASE }}
        >
          <Lirio tamanho={92} />
        </motion.span>
        <motion.span
          className="faby-abertura-lirio faby-abertura-lirio-2"
          initial={{ opacity: 0, scale: 0.6, rotate: 30 }}
          animate={{ opacity: 1, scale: 1, rotate: 16 }}
          transition={{ duration: 0.9, delay: 0.5, ease: EASE }}
        >
          <Lirio tamanho={66} />
        </motion.span>

        <motion.div
          className="faby-abertura-polaroid"
          initial={{ opacity: 0, y: 40, rotate: 6, scale: 0.92 }}
          animate={{ opacity: 1, y: 0, rotate: -4, scale: 1 }}
          transition={{ type: "spring", stiffness: 110, damping: 14, delay: 0.1 }}
        >
          <motion.div animate={flutua} transition={{ duration: 5, repeat: Infinity, ease: "easeInOut" }}>
            <div className="faby-polaroid-frente faby-polaroid-solta">
              <span className="faby-fita faby-fita-polaroid" aria-hidden="true" />
              <img src="/faby/fotos/estrelinha.webp" alt="a faby com a presilha de estrelinha" width="720" height="900" />
              <span className="faby-polaroid-legenda">minha pessoa favorita ⭐</span>
            </div>
          </motion.div>
        </motion.div>

        <motion.div
          className="faby-abertura-melody"
          initial={{ opacity: 0, x: 30, rotate: 20 }}
          animate={{ opacity: 1, x: 0, rotate: 8 }}
          transition={{ type: "spring", stiffness: 140, damping: 12, delay: 0.7 }}
        >
          <motion.div
            animate={reduzir ? undefined : { rotate: [0, -6, 0, 6, 0] }}
            transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
          >
            <PixelSprite name="myMelody" size={96} alt="My Melody" />
          </motion.div>
        </motion.div>

        {BRILHOS.map((b, i) => (
          <span
            key={i}
            className="faby-abertura-brilho"
            style={{ top: b.top, left: b.left, right: b.right, animationDelay: `${b.atraso}s` }}
          >
            <Brilho tamanho={b.tamanho} />
          </span>
        ))}
      </div>

      <motion.h1
        className="faby-abertura-ola"
        initial={{ opacity: 0, y: 18 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.7, delay: 0.45, ease: EASE }}
      >
        {ABERTURA.ola}
        <PixelSprite name="bow" size={28} className="faby-inline-sprite faby-ola-laco" />
      </motion.h1>

      <motion.p
        className="faby-abertura-frase"
        initial={{ opacity: 0, y: 18 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.7, delay: 0.58, ease: EASE }}
      >
        {ABERTURA.frase}
      </motion.p>

      <motion.button
        type="button"
        className="faby-botao faby-botao-grande"
        onClick={descer}
        whileTap={{ scale: 0.95 }}
        initial={{ opacity: 0, y: 18 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.7, delay: 0.7, ease: EASE }}
      >
        {ABERTURA.botao}
      </motion.button>

      <span className="faby-desce" aria-hidden="true">
        <PixelSprite name="heart" size={14} />
        <PixelSprite name="heart" size={10} />
      </span>
    </header>
  );
}

function Faby() {
  useAmbientePagina();
  const visitas = useVisitas();

  return (
    <div className="faby">
      <div className="faby-xadrez" aria-hidden="true" />
      <div className="faby-fundo" aria-hidden="true">
        {ENFEITES.map((e, i) => (
          <span key={`${e.classe}-${i}`} className={`faby-enfeite ${e.classe}`}>
            <PixelSprite name={e.nome} size={e.tamanho} />
          </span>
        ))}
        {PETALAS.map((i) => (
          <span key={i} className={`faby-petala faby-petala-${i + 1}`} />
        ))}
      </div>

      <main className="faby-shell">
        <Abertura />
        <Bilhetinho />
        <div id="faby-historinha" />
        <Contador />
        <Polaroids />
        <Cartinha />
        {/* a casinha (faby/Casinha.jsx) fica guardada por enquanto */}
        <Perguntas />
        <Motivos />
        <Frasinhas />
        <Final />

        <footer className="faby-rodape">
          <PixelSprite name="coelhinha" size={30} alt="coelhinha" />
          <p>
            <PixelSprite name="heart" size={14} className="faby-inline-sprite" />
            {RODAPE.texto}
          </p>
          {visitas > 0 && <p className="faby-rodape-visitas">{RODAPE.visitas(visitas)}</p>}
        </footer>
      </main>
    </div>
  );
}

export default Faby;
